import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ 
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    if (file.mimetype === 'application/pdf') {
      cb(null, true);
    } else {
      cb(new Error('Only PDF files are allowed'));
    }
  }
});

export interface ParsedResumeRequest extends Request {
  file?: Express.Multer.File;
}

router.post('/parse-pdf', upload.single('resume'), async (req: ParsedResumeRequest, res: Response) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'No resume file uploaded' });
    }

    const pdfData = await pdfParse(req.file.buffer);
    const cleanedText = pdfData.text
      .replace(/\s+/g, ' ')
      .trim();

    return res.status(200).json({
      success: true,
      filename: req.file.originalname,
      numpages: pdfData.numpages,
      text: cleanedText,
    });
  } catch (error: any) {
    return res.status(500).json({ error: 'Failed to parse PDF resume', details: error.message });
  }
});

export default router;

import { useState, useMemo } from 'react';

export interface KeywordMatchResult {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  totalJobKeywords: number;
}

export function useKeywordScorer(resumeText: string, jobDescription: string) {
  const [isAnalyzing, setIsAnalyzing] = useState<boolean>(false);

  const analysisResult = useMemo<KeywordMatchResult>(() => {
    if (!resumeText || !jobDescription) {
      return { matchScore: 0, matchedKeywords: [], missingKeywords: [], totalJobKeywords: 0 };
    }

    const cleanAndTokenize = (text: string) => {
      return Array.from(new Set(
        text.toLowerCase()
          .replace(/[^a-z0-9\+\#\. ]/g, '')
          .split(/\s+/
          )
          .filter(word => word.length > 2)
      ));
    };

    const jobKeywords = cleanAndTokenize(jobDescription);
    const resumeWords = new Set(cleanAndTokenize(resumeText));

    const matchedKeywords: string[] = [];
    const missingKeywords: string[] = [];

    jobKeywords.forEach(keyword => {
      if (resumeWords.has(keyword)) {
        matchedKeywords.push(keyword);
      } else {
        missingKeywords.push(keyword);
      }
    });

    const matchScore = jobKeywords.length > 0 
      ? Math.round((matchedKeywords.length / jobKeywords.length) * 100)
      : 0;

    return {
      matchScore,
      matchedKeywords,
      missingKeywords,
      totalJobKeywords: jobKeywords.length
    };
  }, [resumeText, jobDescription]);

  return {
    ...analysisResult,
    isAnalyzing,
    setIsAnalyzing
  };
}
